17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.Map;
25	import java.util.regex.Pattern;
26	
27	import org.slf4j.Logger;
28	import org.slf4j.LoggerFactory;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Dedicated audit logger for owner lifecycle side-effects. */
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    /**
67	     * Pragmatic check for a syntactically valid email address: a non-empty local
68	     * part, a single '@', and a domain with at least one dot-separated label.
69	     */
70	    private static final Pattern EMAIL_PATTERN =
71	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
72	
73	    /**
74	     * Common street-type abbreviations expanded during address normalization,
75	     * keyed by their upper-cased form.
76	     */
77	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
78	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper) {
92	        this.clinicService = clinicService;
93	        this.ownerMapper = ownerMapper;
94	        this.petMapper = petMapper;
95	        this.visitMapper = visitMapper;
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
101	        Collection<Owner> owners;
102	        if (lastName != null) {
103	            owners = this.clinicService.findOwnerByLastName(lastName);
104	        } else {
105	            owners = this.clinicService.findAllOwners();
106	        }
107	        if (owners.isEmpty()) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
116	        Owner owner = this.clinicService.findOwnerById(ownerId);
117	        if (owner == null) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
126	        // Validate & normalize the optional email; reject the create when it is present but invalid.
127	        if (!normalizeEmail(ownerFieldsDto)) {
128	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
129	        }
130	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
131	        // abbreviations) and store the normalized form back on the DTO so it is what gets
132	        // persisted and compared. Reject the create when the address is blank once normalized.
133	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
134	        if (canonicalAddress.isBlank()) {
135	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
136	        }
137	        ownerFieldsDto.setAddress(canonicalAddress);
138	        // Reject the create when the owner's city is already at capacity, i.e. it already
139	        // contains 50 or more owners (compared case-insensitively).
140	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
141	            return new ResponseEntity<>(HttpStatus.CONFLICT);
142	        }
143	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
144	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
145	        if (normalizedTelephone == null) {
146	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
147	        }
148	        // Reject the create if any existing owner already uses this telephone (compared in E.164 form).
149	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
150	            .map(Owner::getTelephone)
151	            .map(OwnerRestControllerV1::toE164)
152	            .filter(existing -> existing != null)
153	            .anyMatch(normalizedTelephone::equals);
154	        if (telephoneInUse) {
155	            return new ResponseEntity<>(HttpStatus.CONFLICT);
156	        }
157	        // Reject the create when another owner already shares this owner's last name and address
158	        // (compared case-insensitively with collapsed whitespace), unless the request opts into
159	        // sharing a household.
160	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
161	            String normalizedLastName = normalizeHouseholdKey(ownerFieldsDto.getLastName());
162	            String normalizedAddress = normalizeHouseholdKey(ownerFieldsDto.getAddress());
163	            boolean householdInUse = this.clinicService.findAllOwners().stream()
164	                .anyMatch(existing ->
165	                    normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
166	                        && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress));
167	            if (householdInUse) {
168	                return new ResponseEntity<>(HttpStatus.CONFLICT);
169	            }
170	        }
171	        // Determine the effective registration date — the value supplied on the request, or the
172	        // server's current date when none was supplied — and roll it forward to the next business
173	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
174	        // registration date (membership-number year segment, per-day create-limit) uses this
175	        // adjusted date.
176	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
177	        if (registrationDate == null) {
178	            registrationDate = LocalDate.now();
179	        }
180	        registrationDate = toBusinessDay(registrationDate);
181	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
182	        // owners have already been registered on this (adjusted) business day.
183	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
184	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
185	        }
186	        ownerFieldsDto.setTelephone(normalizedTelephone);
187	        HttpHeaders headers = new HttpHeaders();
188	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
189	        owner.setRegistrationDate(registrationDate);
190	        // Assign the customer code as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
191	        // letters of the city, the upper-cased first three letters of the last name, and a
192	        // per-city 4-digit sequence one greater than the number of owners already in that city.
193	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
194	        // Record how many existing owners already share this owner's first and last name
195	        // (compared case-insensitively) at the moment before this owner is created.
196	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
197	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
198	        // registered on this (adjusted) business day before this owner is created.
199	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
200	        this.clinicService.saveOwner(owner);
201	        // Emit an audit line recording the new owner's id, customer code and registration date.
202	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
203	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
204	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
205	        headers.setLocation(UriComponentsBuilder.newInstance()
206	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
207	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
208	    }
209	
210	    /**
211	     * Validate and normalize the optional owner email in place.
212	     *
213	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
214	     * When present it must be a syntactically valid address; a valid address is
215	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
216	     * present but syntactically invalid, so the caller can reject with 400.
217	     */
218	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
219	        String email = ownerFieldsDto.getEmail();
220	        if (email == null || email.isBlank()) {
221	            ownerFieldsDto.setEmail(null);
222	            return true;
223	        }
224	        String normalized = email.trim().toLowerCase(Locale.ROOT);
225	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
226	            return false;
227	        }
228	        ownerFieldsDto.setEmail(normalized);
229	        return true;
230	    }
231	
232	    /**
233	     * Normalize an owner address: trim, collapse each run of whitespace to a single
234	     * space, upper-case, and expand common street-type abbreviations
235	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
236	     * A {@code null} value normalizes to the empty string.
237	     */
238	    private static String normalizeAddress(String value) {
239	        if (value == null) {
240	            return "";
241	        }
242	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
243	        if (collapsed.isEmpty()) {
244	            return "";
245	        }
246	        String[] tokens = collapsed.split(" ");
247	        StringBuilder sb = new StringBuilder(collapsed.length());
248	        for (int i = 0; i < tokens.length; i++) {
249	            if (i > 0) {
250	                sb.append(' ');
251	            }
252	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
253	        }
254	        return sb.toString();
255	    }
256	
257	    /**
258	     * Normalize an owner household field (last name or address) for duplicate detection:
259	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
260	     * A {@code null} value normalizes to the empty string.
261	     */
262	    private static String normalizeHouseholdKey(String value) {
263	        if (value == null) {
264	            return "";
265	        }
266	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
267	    }
268	
269	    /**
270	     * Normalize a telephone number to E.164 form.
271	     *
272	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
273	     * explicit leading {@code '+'} and country code it is kept; otherwise the
274	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
275	     * dropped from the national digits. The result must contain 8 to 15 digits
276	     * after the {@code '+'}.
277	     *
278	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
279	     *         the input is absent or cannot form a valid E.164 number.
280	     */
281	    private static String toE164(String raw) {
282	        if (raw == null) {
283	            return null;
284	        }
285	        String trimmed = raw.trim();
286	        boolean hasCountryCode = trimmed.startsWith("+");
287	        // Strip spaces, dashes and brackets.
288	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
289	        String digits;
290	        if (hasCountryCode) {
291	            // Keep the explicit country code; drop the leading '+' for validation.
292	            digits = stripped.substring(1);
293	        } else {
294	            // No country code: assume '+61' and drop a single leading '0'.
295	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
296	            digits = "61" + national;
297	        }
298	        if (!digits.matches("\\d{8,15}")) {
299	            return null;
300	        }
301	        return "+" + digits;
302	    }
303	
304	    /**
305	     * Build the next customer code, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}.
306	     *
307	     * <p>{@code CITY3} is the upper-cased first three letters of {@code city} and
308	     * {@code LAST3} the upper-cased first three letters of {@code lastName} (fewer if
309	     * the value is shorter). {@code NNNN} is a per-city 4-digit zero-padded sequence
310	     * equal to one more than the number of owners already in that city
311	     * (e.g. {@code 'SYD-SMI-0007'}).
312	     */
313	    /**
314	     * Count the existing owners whose first and last name match the given names,
315	     * compared case-insensitively. Used to record an owner's namesake count at the
316	     * moment before it is created.
317	     */
318	    private int countNamesakes(String firstName, String lastName) {
319	        return (int) this.clinicService.findAllOwners().stream()
320	            .filter(existing -> existing.getFirstName() != null
321	                && existing.getFirstName().equalsIgnoreCase(firstName)
322	                && existing.getLastName() != null
323	                && existing.getLastName().equalsIgnoreCase(lastName))
324	            .count();
325	    }
326	
327	    private String nextCustomerCode(String city, String lastName) {
328	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
329	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
330	        int sequence = countOwnersInCity(city) + 1;
331	        return String.format("%s-%s-%04d", city3, last3, sequence);
332	    }
333	
334	    /**
335	     * Count the existing owners located in the given city, compared case-insensitively.
336	     * Used to derive the per-city 4-digit sequence in the customer code.
337	     */
338	    private int countOwnersInCity(String city) {
339	        return (int) this.clinicService.findAllOwners().stream()
340	            .filter(existing -> existing.getCity() != null
341	                && existing.getCity().equalsIgnoreCase(city))
342	            .count();
343	    }
344	
345	    /**
346	     * Count the existing owners whose registration date is the given (adjusted business) date.
347	     * Used to enforce the per-day sign-up limit.
348	     */
349	    private int countOwnersRegisteredOn(LocalDate date) {
350	        return (int) this.clinicService.findAllOwners().stream()
351	            .filter(existing -> date.equals(existing.getRegistrationDate()))
352	            .count();
353	    }
354	
355	    /**
356	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
357	     * the following Monday; a weekday is returned unchanged.
358	     */
359	    private static LocalDate toBusinessDay(LocalDate date) {
360	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
361	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
362	            date = date.plusDays(1);
363	        }
364	        return date;
365	    }
366	
367	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
368	    @Override
369	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
370	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
371	        if (currentOwner == null) {
372	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
373	        }
374	        if (!normalizeEmail(ownerFieldsDto)) {
375	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
376	        }
377	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
378	        if (normalizedTelephone == null) {
379	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
380	        }
381	        currentOwner.setAddress(ownerFieldsDto.getAddress());
382	        currentOwner.setCity(ownerFieldsDto.getCity());
383	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
384	        currentOwner.setLastName(ownerFieldsDto.getLastName());
385	        currentOwner.setTelephone(normalizedTelephone);
386	        currentOwner.setEmail(ownerFieldsDto.getEmail());
387	        this.clinicService.saveOwner(currentOwner);
388	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
389	    }
390	
391	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
392	    @Transactional
393	    @Override
394	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
395	        Owner owner = this.clinicService.findOwnerById(ownerId);
396	        if (owner == null) {
397	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
398	        }
399	        this.clinicService.deleteOwner(owner);
400	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
401	    }
402	
403	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
404	    @Override
405	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
406	        Owner owner = this.clinicService.findOwnerById(ownerId);
407	        if (owner == null) {
408	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
409	        }
410	        HttpHeaders headers = new HttpHeaders();
411	        Pet pet = petMapper.toPet(petFieldsDto);
412	        owner.setId(ownerId);
413	        pet.setOwner(owner);
414	        pet.getType().setName(null);
415	        this.clinicService.savePet(pet);
